fields.InputDefinition:
{
  "goal": "Open the Chat application and wait for the workspace. Open the conversation list (the sidebar toggle at the top-left if it is collapsed) and type a term such as 'renewal' into its 'Search conversations...' box. A row reading 'Search all of Chat for \"renewal\"' appears beneath the list — click it. Confirm a search panel opens with the typed term carried over, an input placeholder like 'Search conversations, messages, artifacts, collections, and tasks...' and a row of filter buttons: All, Conversations, Messages, Artifacts, Collections, Tasks. Type a few characters and click a filter button (e.g. 'Messages') to confirm the filter selection highlights. Then close the panel with the close (X) button or Escape. Seeing the search panel with its scoped filter buttons render is success — results depend on data and are not required. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
